-- Initial PostgreSQL schema. Existing MariaDB data is not imported automatically.
CREATE TABLE IF NOT EXISTS users (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, roles JSON NOT NULL, active SMALLINT NOT NULL DEFAULT 1, last_seen TIMESTAMP(0) WITHOUT TIME ZONE NULL, last_view VARCHAR(20) NULL);

CREATE TABLE IF NOT EXISTS menu (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, station VARCHAR(20) NOT NULL, price INT NOT NULL, active SMALLINT NOT NULL DEFAULT 1, straw SMALLINT NOT NULL DEFAULT 0, wishes VARCHAR(500) NOT NULL DEFAULT '');

CREATE TABLE IF NOT EXISTS schema_migrations (name VARCHAR(80) PRIMARY KEY, applied_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS menu_addons (menu_id INT NOT NULL, addon_id INT NOT NULL, PRIMARY KEY(menu_id,addon_id), FOREIGN KEY(menu_id) REFERENCES menu(id), FOREIGN KEY(addon_id) REFERENCES menu(id));

CREATE TABLE IF NOT EXISTS dining_tables (id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, active SMALLINT NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS table_visits (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, table_id INT NOT NULL, opened_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, paid_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, paid_by INT NULL, FOREIGN KEY(table_id) REFERENCES dining_tables(id), FOREIGN KEY(paid_by) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS orders (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_key VARCHAR(80) NOT NULL UNIQUE, table_id INT NOT NULL, visit_id INT NULL, user_id INT NOT NULL, note VARCHAR(500) NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, cancelled_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, cancelled_by INT NULL, cancellation_reason VARCHAR(300) NULL, paid_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, paid_by INT NULL, FOREIGN KEY(table_id) REFERENCES dining_tables(id), FOREIGN KEY(visit_id) REFERENCES table_visits(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(cancelled_by) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS tickets (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INT NOT NULL, station VARCHAR(20) NOT NULL, origin VARCHAR(20) NOT NULL DEFAULT 'initial', status VARCHAR(20) NOT NULL DEFAULT 'new', created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, ready_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, collected_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, FOREIGN KEY(order_id) REFERENCES orders(id));

CREATE TABLE IF NOT EXISTS items (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id INT NOT NULL, menu_id INT NOT NULL, name VARCHAR(120) NOT NULL, quantity INT NOT NULL, price INT NOT NULL, note VARCHAR(500) NOT NULL, cancelled_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, cancelled_by INT NULL, cancellation_reason VARCHAR(300) NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(cancelled_by) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS events (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id INT NOT NULL, user_id INT NOT NULL, action VARCHAR(30) NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(user_id) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS order_changes (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_key VARCHAR(80) NOT NULL UNIQUE, order_id INT NOT NULL, user_id INT NOT NULL, action VARCHAR(20) NOT NULL, reason VARCHAR(300) NOT NULL, before_state JSON NULL, after_state JSON NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS station_alerts (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ticket_id INT NOT NULL, kind VARCHAR(30) NOT NULL, description VARCHAR(300) NOT NULL, reason VARCHAR(300) NOT NULL, created_by INT NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, acknowledged_by INT NULL, acknowledged_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(acknowledged_by) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS service_calls (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, station VARCHAR(20) NOT NULL, note VARCHAR(200) NOT NULL DEFAULT '', created_by INT NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, acknowledged_by INT NULL, acknowledged_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, cancelled_at TIMESTAMP(0) WITHOUT TIME ZONE NULL, FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(acknowledged_by) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS payment_events (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, visit_id INT NOT NULL, order_id INT NULL, action VARCHAR(20) NOT NULL, amount INT NOT NULL, reason VARCHAR(300) NOT NULL DEFAULT '', user_id INT NOT NULL, created_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visit_id) REFERENCES table_visits(id), FOREIGN KEY(user_id) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS login_attempts (identity_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, blocked_until TIMESTAMP(0) WITHOUT TIME ZONE NULL, updated_at TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS idx_table_visits_table_id_paid_at ON table_visits (table_id,paid_at);

CREATE INDEX IF NOT EXISTS idx_tickets_status_station ON tickets (status,station);

CREATE INDEX IF NOT EXISTS idx_order_changes_order_id ON order_changes (order_id);

CREATE INDEX IF NOT EXISTS idx_station_alerts_acknowledged_at_ticket_id ON station_alerts (acknowledged_at,ticket_id);

CREATE INDEX IF NOT EXISTS idx_service_calls_station_acknowledged_at_cancelled_at ON service_calls (station,acknowledged_at,cancelled_at);

CREATE INDEX IF NOT EXISTS idx_payment_events_visit_id_id ON payment_events (visit_id,id);

CREATE INDEX IF NOT EXISTS idx_login_attempts_updated_at ON login_attempts (updated_at);
